export function getTranslation(questionId, lang) {
  return TRANSLATIONS[questionId]?.[lang] || null;
}

export function getAvailableLanguages(questionId) {
  const entry = TRANSLATIONS[questionId];
  return entry ? Object.keys(entry) : [];
}
